const N=140,parts=[];for(let i=0;i<N;i++){parts.push({x:Math.random()*W(),y:H()*0.6+Math.random()*H()*0.4,r:1+Math.random()*2.2,sp:0.15+Math.random()*0.35,ph:Math.random()*6.28,drift:(Math.random()-0.5)*0.4,tw:0.5+Math.random()*1.5,trail:[]});}
const rays=[];for(let i=0;i<5;i++){rays.push({ang:(-0.5+Math.random())*0.6+((i%2)?2.6:0),len:H()*0.35,x:(i%2)?W()*0.85:W()*0.15,y:(i%2)?H()*0.12:H()*0.9,op:0.05+Math.random()*0.08});}
let t=0;
function frame(){
 t+=0.01;
 const w=W(),h=H();
 ctx.clearRect(0,0,w,h);
 ctx.save();
 rays.forEach((r,i)=>{
 const a=r.ang+Math.sin(t*0.3+i)*0.05;
 const grad=ctx.createLinearGradient(r.x,r.y,r.x+Math.cos(a)*r.len,r.y+Math.sin(a)*r.len);
 grad.addColorStop(0,'rgba(246,196,83,'+r.op+')');
 grad.addColorStop(1,'rgba(246,196,83,0)');
 ctx.strokeStyle=grad;
 ctx.lineWidth=14+8*Math.sin(t+i);
 ctx.beginPath();
 ctx.moveTo(r.x,r.y);
 ctx.lineTo(r.x+Math.cos(a)*r.len,r.y+Math.sin(a)*r.len);
 ctx.stroke();
 });
 ctx.restore();
 for(const p of parts){
 p.y-=p.sp;
 p.x+=Math.sin(t*2+p.ph)*p.drift;
 p.ph+=0.01;
 if(p.y<-10){p.y=h+10;p.x=Math.random()*w;}
 p.trail.push({x:p.x,y:p.y});
 if(p.trail.length>14)p.trail.shift();
 const flick=0.4+0.6*Math.abs(Math.sin(t*p.tw+p.ph));
 for(let j=0;j<p.trail.length;j++){
 const tp=p.trail[j];
 const a=(j/p.trail.length)*0.5*flick;
 const rad=p.r*(j/p.trail.length);
 const grad=ctx.createRadialGradient(tp.x,tp.y,0,tp.x,tp.y,rad*4+2);
 grad.addColorStop(0,'rgba(253,243,231,'+a+')');
 grad.addColorStop(0.5,'rgba(246,196,83,'+a*0.6+')');
 grad.addColorStop(1,'rgba(142,124,195,0)');
 ctx.fillStyle=grad;
 ctx.beginPath();
 ctx.arc(tp.x,tp.y,rad*4+2,0,6.28);
 ctx.fill();
 }
 }
 requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
